#include <stdio.h>
#include <string.h>

int main() {
    int N;
    char S[300005];
    scanf("%d", &N);
    scanf("%s", S);

    // prefix counts
    long long prefixJ[300005] = {0};
    long long prefixJO[300005] = {0};
    long long prefixJOI[300005] = {0};

    for (int i = 0; i < N; i++) {
        if (i > 0) {
            prefixJ[i] = prefixJ[i-1];
            prefixJO[i] = prefixJO[i-1];
            prefixJOI[i] = prefixJOI[i-1];
        }
        if (S[i] == 'J') {
            prefixJ[i]++;
        } else if (S[i] == 'O') {
            prefixJO[i] += prefixJ[i];
        } else if (S[i] == 'I') {
            prefixJOI[i] += prefixJO[i];
        }
    }

    // suffix counts for O->I and I
    long long suffixO[300005] = {0};
    long long suffixOI[300005] = {0};
    long long suffixI[300005] = {0};

    for (int i = N-1; i >= 0; i--) {
        if (i < N-1) {
            suffixO[i] = suffixO[i+1];
            suffixOI[i] = suffixOI[i+1];
            suffixI[i] = suffixI[i+1];
        }
        if (S[i] == 'I') {
            suffixI[i]++;
        } else if (S[i] == 'O') {
            suffixOI[i] += suffixI[i];
        } else if (S[i] == 'J') {
            suffixO[i] += 0; // not needed but for completeness
        }
    }

    long long baseJOI = prefixJOI[N-1];
    long long maxWays = baseJOI;

    // try inserting at each possible gap (0..N)
    for (int pos = 0; pos <= N; pos++) {
        long long leftJ = (pos > 0) ? prefixJ[pos-1] : 0;
        long long leftJO = (pos > 0) ? prefixJO[pos-1] : 0;
        long long rightI = (pos < N) ? suffixI[pos] : 0;
        long long rightOI = (pos < N) ? suffixOI[pos] : 0;

        // insert 'J'
        long long addJ = rightOI; // J + (OI from right)
        if (baseJOI + addJ > maxWays) maxWays = baseJOI + addJ;

        // insert 'O'
        long long addO = leftJ * rightI; // (J from left) + O + (I from right)
        if (baseJOI + addO > maxWays) maxWays = baseJOI + addO;

        // insert 'I'
        long long addI = leftJO; // (JO from left) + I
        if (baseJOI + addI > maxWays) maxWays = baseJOI + addI;
    }

    printf("%lld\n", maxWays);
    return 0;
}

