    char s[200005];
    scanf("%s", s);

    // Precompute prefix/suffix arrays
    long long j_pre[200005] = {0};   // j_pre[i] = # of J in s[0..i-1]
    long long jo_pre[200005] = {0};  // jo_pre[i] = # of JO subseq in s[0..i-1]
    long long i_suf[200005] = {0};   // i_suf[i] = # of I in s[i..n-1]
    long long oi_suf[200005] = {0};  // oi_suf[i] = # of OI subseq in s[i..n-1]

    for (int i = 1; i <= n; i++) {
        j_pre[i] = j_pre[i-1] + (s[i-1] == 'J');
        jo_pre[i] = jo_pre[i-1] + (s[i-1] == 'O' ? j_pre[i-1] : 0);
    }

    for (int i = n-1; i >= 0; i--) {
        i_suf[i] = i_suf[i+1] + (s[i] == 'I');
        oi_suf[i] = oi_suf[i+1] + (s[i] == 'O' ? i_suf[i+1] : 0);
    }

    // Original JOI count
    long long orig = 0;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'I') orig += jo_pre[i];
    }

    long long best = 0;
    for (int p = 0; p <= n; p++) {
        long long add_J = oi_suf[p];
        long long add_O = j_pre[p] * i_suf[p];
        long long add_I = jo_pre[p];
        long long mx = add_J > add_O ? add_J : add_O;
        if (add_I > mx) mx = add_I;
        if (orig + mx > best) best = orig + mx;
    }

    printf("%lld\n", best);
    return 0;
}

