    scanf("%s", S);

    ll *prefJ = (ll *)calloc(N + 1, sizeof(ll));
    ll *prefO = (ll *)calloc(N + 1, sizeof(ll));
    ll *prefI = (ll *)calloc(N + 1, sizeof(ll));

    for (int i = 0; i < N; i++) {
        prefJ[i + 1] = prefJ[i] + (S[i] == 'J');
        prefO[i + 1] = prefO[i] + (S[i] == 'O');
        prefI[i + 1] = prefI[i] + (S[i] == 'I');
    }

    ll original = 0;
    ll cntJ = 0, cntJO = 0;
    for (int i = 0; i < N; i++) {
        if (S[i] == 'J') cntJ++;
        else if (S[i] == 'O') cntJO += cntJ;
        else if (S[i] == 'I') original += cntJO;
    }

    ll ans = 0;

    for (int k = 0; k <= N; k++) {
        ll leftJ = prefJ[k];
        ll leftO = prefO[k];
        ll rightO = prefO[N] - prefO[k];
        ll rightI = prefI[N] - prefI[k];

        ll addJ = rightO * rightI;   // insert 'J' at gap k
        ll addO = leftJ * rightI;    // insert 'O' at gap k
        ll addI = leftJ * leftO;     // insert 'I' at gap k

        ll bestHere = addJ;
        if (addO > bestHere) bestHere = addO;
        if (addI > bestHere) bestHere = addI;

        if (original + bestHere > ans) ans = original + bestHere;
    }

    printf("%lld\n", ans);

    free(S);
    free(prefJ);
    free(prefO);
    free(prefI);
    return 0;
}

