        suffO[i] = suffO[i+1] + (S[i-1] == 'O');
        suffI[i] = suffI[i+1] + (S[i-1] == 'I');
    }

    long long ans = 0;

    // Case 1: Insert at the beginning (position 0)
    for (char c : {'J', 'O', 'I'}) {
        long long ways = 0;
        if (c == 'J') {
