                }
            }
        } else { // 'I'
            for (int k = 1; k <= N; k++) {
                if (S[k-1] == 'O') {
                    ways += (1LL + prefJ[k]) * suffI[k+1];
                }
            }
            // Also consider I as the third stamp
            for (int i = 1; i <= N; i++) {
                if (S[i-1] == 'J') {
                    ways += (long long)prefO[i] * 1; // O from before, I is new
                }
            }
        }
        ans = max(ans, ways);
    }

    // Case 3: Insert in the middle positions (1 to N-1)
    for (int pos = 1; pos <= N-1; pos++) {
        long long base = 0;
        // Count existing J-O-I triples
        for (int k = 1; k <= N; k++) {
            if (S[k-1] == 'O') {
                base += (long long)prefJ[k] * suffI[k+1];
            }
        }

        for (char c : {'J', 'O', 'I'}) {
