                    }
                }
                // Subtract old triples that used the old character at pos as J? No, because we're inserting, not replacing.
                // Actually we are inserting, so all existing triples remain. We just add new ones.
            } else if (c == 'O') {
                // New O at pos: adds new triples where this O is second
                long long leftJ = prefJ[pos] + (S[pos-1]=='J'?1:0); // including the inserted? no, inserted is O
                leftJ = prefJ[pos]; // J's before this position
                long long rightI = suffI[pos+1]; // I's after this position
                ways += leftJ * rightI;
                // Also new triples where this O is second and I is the inserted? no, inserted is O
            } else { // 'I'
                // New I at pos: adds new triples where this I is third
                for (int i = 1; i <= pos; i++) {
                    if (S[i-1] == 'J') {
                        ways += (long long)prefO[i] * 1; // O before i? Actually need J then O then I
                        // Wait: J at i, O somewhere between i+1 and pos, I at pos
                        long long oCount = prefO[pos] - prefO[i];
                        ways += oCount;
                    }
                }
            }
            ans = max(ans, ways);
        }
    }

    // Simpler approach: try all positions and all characters
    // Actually the above is getting messy. Let's do a clean O(N) per insertion point.

    // Reset and do clean O(N^2) for small N? N up to? Not specified, but likely large.
    // Let's do O(N) per position, total O(N^2) might be too big.
    // Better: precompute contributions.

    // We'll compute answer by trying each possible insertion point and character efficiently.
    // Let's do it properly:

    long long finalAns = 0;

    // Precompute total existing J-O-I triples
    long long totalExisting = 0;
    long long totalJ = prefJ[N], totalO = prefO[N], totalI = prefI[N];
    for (int k = 1; k <= N; k++) {
        if (S[k-1] == 'O') {
            totalExisting += (long long)prefJ[k] * suffI[k+1];
        }
    }

    // Try inserting at each position (0 to N) with each character
    for (int pos = 0; pos <= N; pos++) {
        for (char c : {'J', 'O', 'I'}) {
            long long cur = totalExisting;

            if (c == 'J') {
                // New J at pos: adds triples where this J is first, then an O, then an I
                // Count pairs (O, I) after pos
                for (int k = pos+1; k <= N; k++) {
                    if (S[k-1] == 'O') {
                        cur += suffI[k+1];
                    }
                }
            } else if (c == 'O') {
                // New O at pos: adds triples where a J before pos, this O, an I after pos
                long long leftJ = prefJ[pos];
                long long rightI = suffI[pos+1];
                cur += leftJ * rightI;
            } else { // 'I'
                // New I at pos: adds triples where a J before pos, an O between that J and pos
                for (int i = 1; i <= pos; i++) {
                    if (S[i-1] == 'J') {
                        cur += prefO[pos] - prefO[i];
                    }
                }
            }
            finalAns = max(finalAns, cur);
        }
    }

    cout << finalAns << "\n";
    return 0;
}

