    cin >> N >> S;

    vector<long long> prefJ(N + 1, 0), prefO(N + 1, 0), prefI(N + 1, 0);
    for (int i = 0; i < N; ++i) {
        prefJ[i + 1] = prefJ[i] + (S[i] == 'J');
        prefO[i + 1] = prefO[i] + (S[i] == 'O');
        prefI[i + 1] = prefI[i] + (S[i] == 'I');
    }

    // Existing number of JOI subsequences
    long long base = 0;
    long long cntJ = 0, cntJO = 0;
    for (char c : S) {
        if (c == 'J') cntJ++;
        else if (c == 'O') cntJO += cntJ;
        else if (c == 'I') base += cntJO;
    }

    long long ans = 0;

    // Insert at gap k: before S[k], where k in [0..N]
    for (int k = 0; k <= N; ++k) {
        long long leftJ = prefJ[k];
        long long leftO = prefO[k];
        long long rightO = prefO[N] - prefO[k];
        long long rightI = prefI[N] - prefI[k];

        // New store is used as:
        // 'J': choose O and I on the right
        long long addJ = rightO * rightI;

        // 'O': choose J on the left and I on the right
        long long addO = leftJ * rightI;

        // 'I': choose J and O on the left
        long long addI = leftJ * leftO;

        ans = max(ans, base + max({addJ, addO, addI}));
    }

    cout << ans << '\n';
    return 0;
}
